/**
 * Generated by Gemini AI - Attempt 1
 * Processes bank statement data from Excel
 * @param {Array} rawData - Array of rows from bank statement Excel (`sheet_to_json` with `header: 1`)
 * @returns {Object} Processed bank statement data
 */
function processBankStatement(rawData) {
  const bank_details = extractBankDetailsFromRows(rawData)
  const transactions = []
  let headerRowIndex = -1
  let colIndexMap = {}

  // Helper function to parse dates
  function parseDate(dateString) {
    if (!dateString) return null

    // XLSX may already return Date objects when `cellDates: true`
    if (dateString instanceof Date && !isNaN(dateString.getTime())) {
      const year = dateString.getFullYear()
      const month = String(dateString.getMonth() + 1).padStart(2, '0')
      const day = String(dateString.getDate()).padStart(2, '0')
      return `${year}-${month}-${day}`
    }

    // Attempt to parse as Excel date serial number
    if (typeof dateString === 'number') {
      const excelEpoch = new Date(Date.UTC(1899, 11, 31))
      const javascriptDate = new Date(excelEpoch.getTime() + (dateString - 1) * 24 * 60 * 60 * 1000)
      const year = javascriptDate.getFullYear()
      const month = String(javascriptDate.getMonth() + 1).padStart(2, '0')
      const day = String(javascriptDate.getDate()).padStart(2, '0')
      return `${year}-${month}-${day}`
    }

    // Convert to string for pattern matching
    const dateStr = String(dateString).trim()

    // Attempt to parse various date formats
    const dateFormats = [
      { format: /(\d{2})\/(\d{2})\/(\d{4})/, order: [1, 2, 3] }, // DD/MM/YYYY
      { format: /(\d{2})-(\w+)-(\d{4})/, order: [1, 2, 3] }, // DD-Mon-YYYY
      { format: /(\d{2})-(\d{2})-(\d{4})/, order: [1, 2, 3] }, // DD-MM-YYYY
      { format: /(\d{2})\/(\d{2})\/(\d{2,4})/, order: [1, 2, 3] }, // DD/MM/YY or DD/MM/YYYY
      { format: /(\d{4})-(\d{2})-(\d{2})/, order: [3, 2, 1] }, //YYYY-MM-DD
      { format: /(\d{2})-(\w{3})-(\d{2})/, order: [1, 2, 3] }, //DD-MON-YY
    ]

    for (const dateFormat of dateFormats) {
      const match = dateStr.match(dateFormat.format)
      if (match) {
        let year = match[dateFormat.order[2]]
        if (year.length === 2) {
          year = `20${year}` // Assuming 21st century for 2-digit years
        }
        const month = match[dateFormat.order[1]]
        const day = match[dateFormat.order[0]]

        //Convert month abbreviations to number
        const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
        let monthNumber = month
        if (isNaN(month)) {
          const monthIndex = months.findIndex((m) => m.toLowerCase() == month.toLowerCase())
          monthNumber = String(monthIndex + 1).padStart(2, '0')
        }

        return `${year}-${String(monthNumber).padStart(2, '0')}-${String(day).padStart(2, '0')}`
      }
    }
    return null
  }

  // Helper function to clean amount
  function cleanAmount(amountString) {
    if (!amountString) return null
    const cleanedString = String(amountString).replace(/[^0-9.-]+/g, '')
    const parsedAmount = parseFloat(cleanedString)
    return isNaN(parsedAmount) ? null : parsedAmount
  }

  function normalizeHeaderCell(value) {
    if (value === null || value === undefined) return ''
    return String(value)
      .trim()
      .toLowerCase()
      .replace(/[\u00A0]/g, ' ')
      .replace(/[().]/g, ' ')
      .replace(/\s+/g, ' ')
      .replace(/[^a-z0-9 ]+/g, '')
      .trim()
  }

  // Bank details: see extractBankDetailsFromRows(rawData) above (array-of-arrays scan).

  // 2. Identify Header Row and Create Column Index Mapping (BOB cash credit / statement)
  for (let i = 0; i < rawData.length; i++) {
    const row = rawData[i]
    if (!row) continue

    if (!Array.isArray(row)) continue
    const normalized = row.map((cell) => normalizeHeaderCell(cell))

    const hasDate = normalized.some((v) => v.includes('tran date') || (v.includes('date') && !v.includes('value')))
    const hasNarr = normalized.some((v) => v.includes('narration') || v.includes('description') || v.includes('particular') || v.includes('details'))
    const hasDrCr = normalized.some((v) => v.includes('withdrawal') || v.includes('debit') || v.includes('deposit') || v.includes('credit'))
    const hasBal = normalized.some((v) => v.includes('balance'))

    if (hasDate && (hasNarr || hasDrCr) && hasBal) {
      headerRowIndex = i
      for (let j = 0; j < normalized.length; j++) {
        const value = normalized[j]
        if (!value) continue
        if (value.includes('tran date') || (value === 'date') || (value.includes('date') && !value.includes('value'))) {
          colIndexMap.tranDate = j
        } else if (value.includes('value date')) {
          colIndexMap.valueDate = j
        } else if (value.includes('narration') || value.includes('description') || value.includes('particular') || value.includes('details')) {
          colIndexMap.narration = j
        } else if (value.includes('withdrawal') || value.includes('debit') || value.includes('dr')) {
          colIndexMap.debit = j
        } else if (value.includes('deposit') || value.includes('credit') || value.includes('cr')) {
          colIndexMap.credit = j
        } else if (value.includes('balance')) {
          colIndexMap.balance = j
        }
      }
      break
    }
  }

  // 3. Process Transactions
  let voucherNumber = 1
  let lastTxn = null
  for (let i = headerRowIndex + 1; i < rawData.length; i++) {
    const row = rawData[i]
    if (!row) continue

    if (!Array.isArray(row)) continue

    const dateString =
      (colIndexMap.tranDate !== undefined ? row[colIndexMap.tranDate] : null) ??
      (colIndexMap.valueDate !== undefined ? row[colIndexMap.valueDate] : null)
    const descRaw = colIndexMap.narration !== undefined ? row[colIndexMap.narration] : null
    const desc = descRaw !== null && descRaw !== undefined && String(descRaw).trim() ? String(descRaw).trim() : null
    const debitString = colIndexMap.debit !== undefined ? row[colIndexMap.debit] : null
    const creditString = colIndexMap.credit !== undefined ? row[colIndexMap.credit] : null
    const balanceString = colIndexMap.balance !== undefined ? row[colIndexMap.balance] : null

    const date = parseDate(dateString)
    const debit = cleanAmount(debitString)
    const credit = cleanAmount(creditString)
    const balance = cleanAmount(balanceString)

    // Continuation row (multi-line narration): no date, no amounts, narration present
    if (!date && desc && debit === null && credit === null && balance === null && lastTxn) {
      lastTxn.desc = lastTxn.desc ? `${lastTxn.desc} ${desc}` : desc
      continue
    }

    if (!date && !desc && debit === null && credit === null && balance === null) {
      continue // Skip empty rows
    }

    let type = null
    let amount = null

    if (debit !== null) {
      type = 'withdrawal'
      amount = Math.abs(debit) // Ensure amount is positive
    } else if (credit !== null) {
      type = 'deposit'
      amount = Math.abs(credit) // Ensure amount is positive
    }

    if (type && amount !== null && date) {
      const transaction = {
        date: date,
        voucher_number: voucherNumber++,
        amount: amount,
        desc: desc,
        from: null,
        to: null,
        type: type,
        balance: balance !== null ? balance : null,
      }

      transactions.push(transaction)
      lastTxn = transaction
    }
  }

  // 4. Return Result
  return {
    bank_details: bank_details,
    transactions: transactions,
  }
}

// Helper function to extract bank details from array-of-arrays
function extractBankDetailsFromRows(rows) {
  const bank_details = {
    bank_name: null,
    opening_balance: 0,
    ifsc: null,
    address: null,
    city: null,
    account_no: null,
    account_holder_name: null,
    branch_name: null,
    branch_code: null,
  }

  for (let i = 0; i < rows.length; i++) {
    const row = rows[i]
    for (let j = 0; j < row.length; j++) {
      const cell = row[j]
      if (!cell) continue
      const value = String(cell).trim()

      if (value.toLowerCase().includes('account holder name')) {
        const afterColon = value.split(':')[1]
        if (afterColon && afterColon.trim()) {
          bank_details.account_holder_name = afterColon.trim()
        } else {
          for (let k = j + 1; k < row.length; k++) {
            if (row[k]) {
              bank_details.account_holder_name = String(row[k]).trim()
              break
            }
          }
        }
      } else if (value.toLowerCase().includes('branch name')) {
        const afterColon = value.split(':')[1]
        if (afterColon && afterColon.trim()) {
          bank_details.branch_name = afterColon.trim()
        } else {
          for (let k = j + 1; k < row.length; k++) {
            if (row[k]) {
              bank_details.branch_name = String(row[k]).trim()
              break
            }
          }
        }
      } else if (value.toLowerCase().includes('ifsc')) {
        const afterColon = value.split(':')[1]
        if (afterColon && afterColon.trim()) {
          bank_details.ifsc = afterColon.trim()
        } else {
          for (let k = j + 1; k < row.length; k++) {
            if (row[k]) {
              bank_details.ifsc = String(row[k]).trim()
              break
            }
          }
        }
      } else if (value.toLowerCase().includes('address')) {
        const afterColon = value.split(':')[1]
        if (afterColon && afterColon.trim()) {
          bank_details.address = afterColon.trim()
        } else {
          for (let k = j + 1; k < row.length; k++) {
            if (row[k]) {
              bank_details.address = String(row[k]).trim()
              break
            }
          }
        }
      }
      // Add more fields as needed...
    }
  }
  return bank_details
}

module.exports = processBankStatement
